memberdef.initializer:
auto&& result_name = (rexpr);                                                        \
if (!result_name) [[unlikely]] {                                                     \
  AddError(ErrorKind::kInvalidArgument, __VA_ARGS__);                                \
  return *this;                                                                      \
}                                                                                    \
lhs = std::move(result_name.value());
